-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"434d39f8-9068-4899-b468-06ed5663ea6c","n":1,"title":"الخطاب الإشهاري (المفهوم والأنواع)","passage":"يرمي الخطاب الإشهاري إلى تعريف الجمهور بخدمة أو فكرة أو تشجيع سلوك محدد، وقد يستعمل صورة وشعارًا وحجة. يميز الناقد الإعلان التجاري من حملة التوعية، ويتحقق من الادعاءات بدل قبول المبالغة. في مثال مستقل لوحة تعلن وقت معرض كتب دون عبارات نجاح غير مثبتة.","question":"ما العنصر الذي يحدد وظيفة الإعلان؟","correct":"المخاطب والغرض والرسالة","wrong":["حجم الخط وحده","لون الملصق فقط","عدد الصور بلا معنى"],"practice":"قارن إعلانًا تعليميًا وآخر تجاريًا مع تحليل الادعاء والدليل والمخاطب.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"434d39f8-9068-4899-b468-06ed5663ea6c","n":2,"title":"الخطاب الإشهاري","passage":"تؤثر اللغة المختصرة والصورة والتكرار في جذب انتباه جمهور الإعلان، لكن نجاح التصميم لا يبرر إخفاء مصدر المعلومات أو اختراع تخفيض أو نتيجة. في تدريب ضاديوم يعد فريق ملصقًا يحث الطلاب على استعارة الكتب ويحدد شروط المشاركة بوضوح.","question":"أي ممارسة تحافظ على صدق الإعلان؟","correct":"إعلان شروط المشاركة القابلة للتحقق","wrong":["وعود مجهولة","إخفاء التفاصيل","إحصاءات مختلقة"],"practice":"اكتب نصًا إشهاريًا أصليًا لمبادرة مدرسية يتضمن دعوة وبيانات واضحة وتحفظًا مناسبًا.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"434d39f8-9068-4899-b468-06ed5663ea6c","n":3,"title":"جملة صلة الموصول","passage":"تأتي جملة صلة الموصول بعد اسم موصول لتحدد المقصود، مثل «قرأنا المقالَ الذي نُشرَ أمس». جملة «نُشر أمس» صلة الموصول لا محل لها من الإعراب في هذا التركيب، ويُراعى رابطها عند الحاجة.","question":"ما الاسم الموصول في «المقال الذي نشر أمس»؟","correct":"الذي","wrong":["المقال","أمس","نشر"],"practice":"أنشئ أربعة أمثلة متنوعة وصلات موصول وحدد الأسماء والروابط.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"434d39f8-9068-4899-b468-06ed5663ea6c","n":4,"title":"الخطاب الفني (المفهوم والأنواع)","passage":"يعبر الخطاب الفني عبر وسيط كالرسم أو المسرح أو السينما أو التصميم عن تجربة أو فكرة، وقد تختلف طرق بنائه وفق النوع والجمهور. لا يعني العمل الفني وثيقة تاريخية حرفية حتى لو استوحى حدثًا حقيقيًا. في مثال مستقل يبتكر الطلاب مشهدًا صامتًا عن التعاون.","question":"أي علامة تميز خطابًا فنيًا عن تقرير وقائع فقط؟","correct":"توظيف وسيط وتشكيل تعبيري لإيصال المعنى","wrong":["وجود أرقام دائمًا","غياب جمهور","منع أي صورة"],"practice":"قارن لوحة أو مشهدًا مأذونًا وتقريرًا عن موضوع واحد، وبيّن اختلاف أساليب التعبير.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"434d39f8-9068-4899-b468-06ed5663ea6c","n":5,"title":"مسرحية أهل الكهف","passage":"تستلزم دراسة مسرحية «أهل الكهف» قراءة نص توفيق الحكيم المقرر للتحقق من الشخصيات والحوار والصراع الدرامي. لا يجوز اختلاق حوار منسوب إلى الكاتب أو استخدام نص قرآني محرَّف. مثال مستقل يناقش شخصيتين تختلفان في فهم مرور الزمن؛ لا يمثل المسرحية.","question":"ما الذي يحدد ملامح الصراع الدرامي في المسرحية؟","correct":"الحوار والأفعال الموثقة داخل المشاهد","wrong":["العنوان وحده","حوار مُخترَع على لسان الكاتب","تخمين نهاية"],"practice":"استخرج من النسخة المدرسية مواجهة درامية صحيحة المصدر وحلل وظيفة الحوار والسياق.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"434d39f8-9068-4899-b468-06ed5663ea6c","n":6,"title":"الاشتقاق","passage":"الاشتقاق تكوين كلمات ترتبط بأصل لغوي مشترك مع اختلاف الصيغة والدلالة، مثل «كتب، كاتب، مكتوب، كتابة». يحتاج الطالب إلى فهم الجذر والوزن وإسناد كل معنى إلى صيغة صحيحة بدل الحكم من اشتراك الحروف فقط.","question":"أي كلمة اسم مفعول من الجذر «كتب»؟","correct":"مكتوب","wrong":["كاتب","كتابة","يكتب"],"practice":"صنّف ستة مشتقات لجذرين مختلفين مع أوزانها ودلالاتها.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"434d39f8-9068-4899-b468-06ed5663ea6c","n":7,"title":"مهارة العمل ضمن فريق","passage":"يساعد العمل الجماعي على توزيع المسؤوليات وتقليل تكرار الجهد عندما يكون الهدف والوقت والأدوار معلنة. في تدريب مستقل يخطط طلاب لمعرض علمي فيحددون من يجمع المصادر ومن يراجع المحتوى ومن يقدم العرض؛ ويُقاس الإنجاز بالنتائج لا بمجرد كثرة الاجتماعات.","question":"ما الذي يحسن مساءلة أعضاء الفريق؟","correct":"توزيع الأدوار ومعايير الإنجاز","wrong":["إخفاء المسؤوليات","مواعيد بلا اتفاق","إلغاء المراجعة"],"practice":"اكتب خطة فريق من أربعة أدوار ومؤشرين لمتابعة التقدم ومعالجة الخلاف.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"2c4757ef-3aa2-451f-bd52-a36a0865f74a","n":1,"title":"المباحث الفلكية عند العرب","passage":"يتطلب تاريخ الفلك عند العرب التحقق من مؤلفات العلماء وأزمنتهم وأدوات الرصد، والتمييز بين تصور قديم ومعلومة علمية حديثة. مثال مستقل يراجع طالب رسمًا لرصد السماء في مخطوط ويقارن تفسيره بمصدر فلكي حديث، ولا ينسب نتيجة غير محققة لعالم.","question":"كيف نوثق إنجازًا فلكيًا تاريخيًا؟","correct":"بمؤلف محقق وسياق علمي ومصدر","wrong":["بحكاية غير مسندة","بتوقع من الاسم","بإهمال التاريخ"],"practice":"وثق آلة أو عملًا فلكيًا من مرجع متخصص وناقش حدود تفسيره العلمي.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"2c4757ef-3aa2-451f-bd52-a36a0865f74a","n":2,"title":"الجملة الواقعة فاعلا أو نائب فاعل","passage":"قد يؤدي المصدر المؤول وظيفة الفاعل في تراكيب مثل «يسرّني أنْ تنجحَ»، حيث يُحلل «أن تنجح» فاعلًا مؤخرًا في وجه نحوي معروف. أما ادعاء وقوع جملة ما نائب فاعل فيحتاج مثالًا مرجعيًا مضبوطًا وتحديد البنية.","question":"ما الموقع الإعرابي للمصدر المؤول «أن تنجح» في المثال؟","correct":"فاعل مؤخر في التحليل المذكور","wrong":["مضاف إليه","أداة نهي","نعت مجرور"],"practice":"راجع مثالين من مرجع نحوي للمصدر المؤول في موضع رفع، وفسر العامل والموقع.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"2c4757ef-3aa2-451f-bd52-a36a0865f74a","n":3,"title":"البحث عن خواص الأضواء","passage":"تحتاج قراءة نص تراثي عن خواص الضوء إلى نسخته المحققة لفهم ملاحظات صاحبه وطريقة الاستدلال، دون نسبة تجربة محددة غير موثقة. في مثال مستقل يقارن طالب شدة الضوء المرصودة عند تغيير موقع مصباح مع الحفاظ على شروط التجربة؛ وهو نموذج مدرسي لا نص تاريخي.","question":"ما الذي يجعل مقارنة قياسات الضوء أكثر دقة؟","correct":"تحديد الشروط وطريقة القياس","wrong":["تغيير المتغيرات كلها دون تسجيل","الاعتماد على اللون وحده","اختلاق النتائج"],"practice":"اكتب وصفًا لتجربة ضوئية آمنة مع فرضية وقياس وحدود، وقارنها بملاحظة تاريخية موثقة.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"2c4757ef-3aa2-451f-bd52-a36a0865f74a","n":4,"title":"الجملة الواقعة مبتدأ أو اسما لناسخ","passage":"بعض التراكيب النحوية تتناول المصدر المؤول في مواقع الأسماء، ويُراجع وقوع جملة في موضع المبتدأ أو اسم الناسخ بمرجع مضبوط؛ فالتفريق بين الجملة والمصدر المؤول مهم. في «أنْ تتعلّمَ خيرٌ لك» يمكن تحليل المصدر المؤول مبتدأ مؤخرًا أو مقدّمًا بحسب التقدير المعتمد.","question":"ما المعلومة اللازمة لإعراب المصدر المؤول؟","correct":"تحديد العامل وموقعه في تركيب الجملة","wrong":["عد الحروف","اسم العلامة فقط","ترتيب الصفحة"],"practice":"ابحث عن مثال موثق لمصدر مؤول مبتدأ، وآخر اسمًا لناسخ، مع توضيح التحليل.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"2c4757ef-3aa2-451f-bd52-a36a0865f74a","n":5,"title":"إكليل الجبل","passage":"قد يستخدم عنوان «إكليل الجبل» لعرض وصف نبات أو نص أدبي، ولا يمكن افتراض محتواه الطبي أو وصفات علاجية منه. في مثال مستقل يصف طالب أوراق نبتة عطرية ويصورها ثم يقارن الاسم العلمي بمصدر نباتي معتمد، دون اقتراح تناولها كدواء.","question":"ما الذي يمنع الخلط بين اسم النبات ودعوى طبية؟","correct":"فحص المصدر العلمي وعدم استنتاج علاج من الاسم","wrong":["اعتبار الرائحة علاجًا مثبتًا","حكاية مجهولة","إلغاء الاسم العلمي"],"practice":"راجع النص المقرر وحدد نوعه أولًا ثم اكتب وصفًا غير علاجي مع مرجع نباتي.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"2c4757ef-3aa2-451f-bd52-a36a0865f74a","n":6,"title":"الجملة الواقعة خبرا لمبتدأ أو لناسخ","passage":"قد يأتي الخبر جملة فعلية أو اسمية إذا استوفى الرابط؛ في «الطالبُ يقرأُ» جملة «يقرأ» في محل رفع خبر، وفي «كان الطالبُ يقرأُ» جملة «يقرأ» في محل نصب خبر كان. تُذكر الحركة والعامل لتجنب الخلط بين الموضعين.","question":"ما محل جملة «يقرأ» في «كان الطالب يقرأ»؟","correct":"في محل نصب خبر كان","wrong":["فاعل كان","مفعول مطلق","مضاف إليه"],"practice":"كوّن أربعة أمثلة لجملة خبر مبتدأ وجملة خبر ناسخ وأعربها.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"2c4757ef-3aa2-451f-bd52-a36a0865f74a","n":7,"title":"مهارة تقديم عرض","passage":"يحتاج العرض إلى سؤال مركزي ونقاط مرتبة وشاهد لكل ادعاء، مع مراعاة زمن الجمهور وإمكانية المراجعة. في مثال مستقل يقدم طالب عرضًا عن تطور أدوات الكتابة ويشرح الفرق بين صورة تاريخية وواقع تقني حديث.","question":"ما الذي يجعل العرض قابلا للتحقق؟","correct":"شواهد ومصادر واضحة","wrong":["تكثير المؤثرات دون دليل","إخفاء الاقتباسات","تقديم الخاتمة فقط"],"practice":"خطط عرضًا شفهيًا لدقيقتين مع شريحتين ومصدرين وتعقيب موجز.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"50a380d1-ea25-43c5-ab5a-02f2b5a4266e","n":1,"title":"النهضة وتياراتها الأدبية","passage":"تختلف اتجاهات النهضة الأدبية العربية في العناية بإحياء التراث والتجديد في الموضوع والشكل، ولا يمكن اختزال جميع الأعمال في مدرسة واحدة. تُختبر السمات بمقارنة نصوص صحيحة النسبة من حقب معروفة.","question":"ما المعيار الصحيح لتحديد ملمح نهضوي؟","correct":"مقارنة شاهدين موثقين وسياقهما","wrong":["تخمين من الاسم","حكم من القافية فقط","تأليف بيت تاريخي"],"practice":"اختر نصًا من مرحلة النهضة ونصًا أقدم وقارن الأسلوب والغرض مع المصادر.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"50a380d1-ea25-43c5-ab5a-02f2b5a4266e","n":2,"title":"الجملة الحالية","passage":"في «دخلتِ الطالبةُ وهي تبتسمُ» تأتي الجملة الاسمية «وهي تبتسم» في محل نصب حال مع رابط الواو والضمير. يميّز التحليل صاحب الحال والمعنى المؤقت من جملة نعتية قد تتبع نكرة.","question":"ما وظيفة «وهي تبتسم» في المثال؟","correct":"جملة حالية","wrong":["فاعل للفعل دخل","مضاف إليه","جواب قسم"],"practice":"أنشئ مثالين لجملة حالية وأخرى نعتية، ثم بين الرابط وصاحب الحال.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"50a380d1-ea25-43c5-ab5a-02f2b5a4266e","n":3,"title":"إني لتطربني الخلال كريمة","passage":"لا يجوز اختلاق أبيات من نص «إني لتطربني الخلال كريمة» أو نسبة موقف للشاعر من العنوان وحده. مثال أصلي يعجب متكلم بصدق صديقه في موقف صعب؛ يصلح لتدريب تفسير الإعجاب بالخلق لا للاستشهاد به على القصيدة.","question":"ما الذي يؤكد صورة الخلق في قصيدة قديمة؟","correct":"شواهد صحيحة من الأبيات","wrong":["انطباع عن العنوان","إضافة شطر مولّد","قصص مجهولة"],"practice":"استخرج من النص الأصلي لفظًا أو صورة تدل على العاطفة وفسرها مع توثيق.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"50a380d1-ea25-43c5-ab5a-02f2b5a4266e","n":4,"title":"الجملة النعتية","passage":"في «رأيتُ طفلًا يحملُ كتابًا» تأتي جملة «يحمل كتابًا» نعتًا للطفل النكرة في الوجه المعروف من التحليل، ويختلف ذلك عن الجملة الحالية في شروطها ومعناها. لا نعد كل جملة تتبع اسمًا نعتًا دون رابط وسياق.","question":"ما موقع «يحمل كتابًا» بعد «طفلًا»؟","correct":"جملة نعتية","wrong":["خبر إن","فاعل رأيت","بدل مفرد"],"practice":"اكتب أربع جمل نعتية مع تحديد المنعوت والرابط، وقارنها بجمل حالية.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"50a380d1-ea25-43c5-ab5a-02f2b5a4266e","n":5,"title":"نشيد الجبار","passage":"يحتاج «نشيد الجبار» إلى نصه الصحيح لتحديد معنى العنوان وموقف المتكلم، ولا يجوز افتراض أن الجبار شخصية تاريخية أو كتابة كلمات منسوبة للشاعر. مثال مستقل يناقش تفاوت القوة والمسؤولية دون اقتباس.","question":"كيف تحدد دلالة كلمة «الجبار» في النص؟","correct":"من الأبيات وسياقها الحقيقي","wrong":["العنوان وحده","تخمين حادثة","شاهد مختلق"],"practice":"اقرأ النص المقرر واستخرج لفظتين تبرزان صورة المتكلم أو المخاطب مع توثيق.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"50a380d1-ea25-43c5-ab5a-02f2b5a4266e","n":6,"title":"أنا","passage":"عنوان «أنا» قد يرد في أكثر من نص أو جنس، ولا يحدد وحده هوية الكاتب أو علاقة المتكلم بالسيرة. تُراجع النسخة المدرسية لمعرفة الضمائر والصور ومقام التعبير، ويستخدم التدريب مثالًا مستقلًا لتأمل الذات دون نسبه لنص معين.","question":"ما الذي يساعد على فهم المتكلم في قصيدة «أنا»؟","correct":"الضمائر والصور والسياق الموثق","wrong":["العنوان وحده","اسم غير مثبت","تخمين القافية"],"practice":"حدد في النص الأصلي ضميرين ووظيفتهما وعلاقة الصورة بفكرة الذات.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"50a380d1-ea25-43c5-ab5a-02f2b5a4266e","n":7,"title":"مهارة تقنيات التفاوض","passage":"يحتاج التفاوض إلى معرفة مصالح الطرفين والبدائل الممكنة ومعايير عادلة للاتفاق، مع إنصات وتوثيق الخطوات. مثال مستقل تفاوض فريقان حول استخدام مختبر المدرسة واتفقا على جدول تجريبي ومراجعة شهرية.","question":"ما الذي يجعل الاتفاق قابلًا للمتابعة؟","correct":"موعد ومعايير ومسؤوليات واضحة","wrong":["وعد شفهي بلا تفاصيل","إلغاء أحد الطرفين","غياب جدول"],"practice":"صمم حوار تفاوض من ستة أدوار حول مورد مدرسي مشترك مع اتفاق قابل للقياس.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"c4da7502-ec4e-440d-b2b1-4fb33c58edfe","n":1,"title":"مجتمع المعرفة","passage":"يقوم مجتمع المعرفة على إنتاج المعرفة وتداولها واستخدامها بصورة نقدية مع إتاحة التعلم، ولا تختزل المشاركة فيه في امتلاك الأجهزة. في مثال مستقل يؤسس طلاب قاعدة مراجع مدرسية مع مؤلف وتاريخ وروابط، ويحدثونها بعد التحقق.","question":"ما الذي يزيد موثوقية قاعدة المراجع في المثال؟","correct":"توثيق المؤلف والتاريخ والمصدر","wrong":["عدد الأجهزة فقط","إخفاء أصل المادة","نسخ روابط عشوائية"],"practice":"ناقش علاقة الوصول للمعلومات بالتحقق منها، مع مثال ومصدر معروف.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"c4da7502-ec4e-440d-b2b1-4fb33c58edfe","n":2,"title":"التضاد","passage":"يظهر التضاد الدلالي في أزواج مثل «قريب وبعيد» و«العدل والظلم»، لكنه لا يعني أن كل كلمتين مختلفتين ضدان. يتحدد التقابل بحسب المعنى والسياق، وقد تختلف درجات التضاد.","question":"أي كلمتين متضادتان؟","correct":"قريب وبعيد","wrong":["كتاب وقلم","مدرسة ومكتبة","مدينة وميناء"],"practice":"اكتب خمسة أزواج متضادة، ثم بين سياقًا يتغير فيه معنى أحد الألفاظ.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"c4da7502-ec4e-440d-b2b1-4fb33c58edfe","n":3,"title":"حوار الثقافات","passage":"ينجح الحوار بين ثقافات مختلفة بتمثيل عادل للآراء وتجنب الصور النمطية وإتاحة الترجمة الدقيقة والإنصات. في مثال مستقل يتعاون طلاب على تفسير أمثال محلية ويشرح كل طرف سياق المثل بدل الحكم على أصحابه.","question":"ما التصرف الذي يدعم الحوار الثقافي؟","correct":"سؤال أصحاب التعبير عن سياقه واحترام اختلافه","wrong":["اختراع معتقد عن الجميع","السخرية من اللغة","الاعتماد على صورة واحدة"],"practice":"اكتب حوارًا متخيلا بين متعلمين من بيئتين يتضمن سؤالًا وتوضيحًا واحترامًا للمصدر.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"c4da7502-ec4e-440d-b2b1-4fb33c58edfe","n":4,"title":"الترادف","passage":"الترادف تقارب معاني ألفاظ مثل «فرِح وسُرّ» في بعض السياقات، لكن لا يجوز افتراض تطابق جميع الظلال الدلالية والاستعمالات؛ يستحسن الرجوع إلى معجم وأمثلة حقيقية.","question":"ما أفضل طريقة للحكم على صلاحية مرادف في جملة؟","correct":"مراجعة السياق والفرق الدلالي","wrong":["التبديل العشوائي","تشابه الوزن فقط","الاعتماد على عدد الحروف"],"practice":"قارن ثلاثة أزواج من الكلمات المتقاربة في جمل مع توضيح فرق سياقي واحد.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"c4da7502-ec4e-440d-b2b1-4fb33c58edfe","n":5,"title":"المجتمع المدني","passage":"يصف مفهوم المجتمع المدني في استعمالات بحثية مؤسسات ومبادرات طوعية خارج بعض أطر السلطة الحكومية والسوق التجارية بحسب التعريف المعتمد، وتختلف النماذج قانونيًا واجتماعيًا. مثال مستقل جمعية تطوعية تنظم ورشة قراءة بمتطوعين وفق قواعد معلنة.","question":"ما الذي يوضح الطابع التطوعي في المثال؟","correct":"مشاركة منظمة بإرادة الأعضاء","wrong":["إجبار المشاركين","العمل سرًا بلا أهداف","إلغاء المسؤوليات"],"practice":"اقرأ تعريفين بحثيين للمجتمع المدني وقارن أوجه الاتفاق والاختلاف في المعايير.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"c4da7502-ec4e-440d-b2b1-4fb33c58edfe","n":6,"title":"الجملة الواقعة في محل جر بالإضافة","passage":"قد تقع جملة فعلية بعد ظرف يضاف إلى الجمل كما في «استمعتُ حينَ شرحَ المعلمُ»، فجملة «شرح المعلم» في محل جر بالإضافة إلى «حين» في التحليل المدرسي المعروف. لا يحسم الموقع من الرسم وحده بل من العامل.","question":"ما موقع جملة «شرح المعلم» بعد «حين»؟","correct":"في محل جر بالإضافة","wrong":["مبتدأ مرفوع","خبر إن","مفعول مطلق"],"practice":"كوّن أربعة تراكيب بظروف مضافة إلى جمل مع بيان إعرابها.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"},{"cid":"4398544e-d25f-4ec6-a6c5-a2ba0026d992","unit":"c4da7502-ec4e-440d-b2b1-4fb33c58edfe","n":7,"title":"مهارة إعداد ورقة عمل","passage":"تحتاج ورقة العمل إلى هدف قابل للقياس وتدرج أسئلة وتعليمات قصيرة ومفتاح تصحيح واضح للموضوعي ومقياس للمفتوح. في نموذج مستقل يعد طالب ورقة لفهم فقرة: سؤال استخراج ثم تفسير ثم تطبيق.","question":"ما العنصر الذي يساعد على تقويم الإجابات بإنصاف؟","correct":"معيار تصحيح واضح مرتبط بالهدف","wrong":["أسئلة بلا تعليمات","حذف هدف التعلم","درجة عشوائية"],"practice":"أعد ورقة عمل من ثلاثة مستويات على فقرة أصلية، مع نموذج تصحيح وتعليمات.","old":"DADYOOM_MR_G13_SCIENTIFIC_OFFICIAL"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='MR' AND c.id=r.cid
    AND g.grade_number=13 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G13_SCIENCE_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G13_SCIENCE_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'MR_G13_SCIENCE_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G13_SCIENCE_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_MR_G13_SCIENCE_ORIGINAL_28_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G13_SCIENCE_ORIGINAL_28_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G13_SCIENCE_ORIGINAL_28_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_MR_G13_SCIENCE_ORIGINAL_28_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G13_SCIENCE_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;